let S={profile:{},items:{},documents:{},orders:[],consent:false,kyc:{checks:[],state:'incomplete'}}, CAT=[], capabilities={}, Q=null, language='English', wizard={}, messages=[], selectedGoals=[], analyticsData=null, selectedOrder='', busy=false, quoteMode='recommended', partnerTab='leads', currentApplicant='K02', registryKind='gst', catalogueFilter='All', wizardEdit='';
