const titleFor=id=>({overview:t('Overview','अवलोकन'),advisor:t('Business advisor','बिज़नेस सलाहकार'),bundle:t('Your bundle','आपका प्लान'),verify:t('Verification','सत्यापन'),orders:t('Order tracker','ऑर्डर की स्थिति'),partner:t('Partner desk','पार्टनर डेस्क'),impact:t('Impact & evidence','प्रभाव और प्रमाण')})[id]||'Overview';
const route=()=>location.hash.slice(1).split('?')[0]||'overview';
const go=id=>{if(route()===id)render();else location.hash=id;$('sidebar').classList.remove('open')};
async function api(path,body){const r=await fetch('/api/'+path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),credentials:'same-origin'});const data=await r.json();if(!r.ok)throw Error(data.error||'This step could not be completed.');return data}
let toastTimer;function toast(message,error=false){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').className='toast visible'+(error?' error':'');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),6500)}
async function task(fn){if(busy)return;busy=true;document.body.classList.add('busy');try{await fn()}catch(e){toast(e.message,true)}finally{busy=false;document.body.classList.remove('busy')}}
function setState(state){S=state;if(S.profile?.language)language=S.profile.language;}
function syncNav(){const sidebar=$('sidebar');sidebar.inert=matchMedia('(max-width:680px)').matches&&!sidebar.classList.contains('open')}
function nav(){const primary=[['overview','grid'],['advisor','spark'],['bundle','box'],['verify','shield'],['orders','route']];$('navigation').innerHTML=primary.map(([id,i])=>`<a href="#${id}" class="nav-link ${route()===id?'active':''}" ${route()===id?'aria-current="page"':''}>${icon(i)}${titleFor(id)}</a>`).join('')+`<div class="nav-divider"></div><div class="nav-section-label">${t('BEHIND THE BUSINESS','व्यवसाय के पीछे')}</div>`+[['partner','people'],['impact','chart']].map(([id,i])=>`<a href="#${id}" class="nav-link ${route()===id?'active':''}" ${route()===id?'aria-current="page"':''}>${icon(i)}${titleFor(id)}</a>`).join('');$('page-name').textContent=titleFor(route());$('workspace-name').textContent=S.registry?.name||S.profile.name||t('Your business','आपका व्यवसाय');$('language-button').innerHTML=`अ <span>${language==='Hindi'?'हिन्दी':'English'}</span><span class="chevron">⌄</span>`;document.documentElement.lang=language==='Hindi'?'hi':'en';}
function stepper(current){return `<div class="launch-stepper">${[['advisor',t('Discover','जानें')],['bundle',t('Build','बनाएँ')],['verify',t('Verify','सत्यापित करें')],['orders',t('Go live','शुरू करें')]].map(([id,name],i)=>`${i?'<i></i>':''}<span class="${id===current?'active':''}"><b>${i+1}</b>${name}</span>`).join('')}</div>`}
function pageHeading(title,subtitle,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${t('A LITTLE CLARITY. A LOT OF POSSIBILITY.','साफ़ रास्ता। नई संभावनाएँ।')}</div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`}
function render(){nav();syncNav();const views={overview:home,advisor:advisor,bundle:bundle,verify:verify,orders:orders,partner:partner,impact:impact};$('main').innerHTML=`<div class="fade-in">${(views[route()]||home)()}</div>${Q&&['bundle','verify'].includes(route())?`<div class="mobile-action-dock"><div><strong>${money(Q.total,2)}</strong><small>${t('/month, incl. GST','/माह, GST सहित')}</small></div><button class="button" data-action="${route()==='verify'?'checkout':'goto'}" data-value="verify">${route()==='verify'?t('Review plan','प्लान देखें'):t('Continue','जारी रखें')}${icon('arrow')}</button></div>`:''}`;if(route()==='partner'&&!analyticsData)loadAnalytics();}
function home(){const hasPlan=!!Q;const isActive=S.orders?.[0]?.status==='active';const stage=isActive?4:S.orders?.length?3:S.registry?2:hasPlan?1:0;return `${pageHeading(t('Good things start small.','बड़ी शुरुआत, छोटे कदमों से।'),t('Your next chapter deserves a simpler digital setup. Let’s build it together.','आपके व्यवसाय की अगली उड़ान के लिए एक आसान डिजिटल शुरुआत।'),`<div class="page-date">${icon('calendar')}${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</div>`)}
<section class="hero"><div class="hero-copy"><div class="eyebrow">${t('SMALL BUSINESS. BIG POSSIBILITIES.','छोटा व्यवसाय। बड़ी संभावनाएँ।')}</div><h2>${t('More business.<br>Less figuring it out.','व्यवसाय पर ध्यान दें।<br>उलझनों पर नहीं।')}</h2><p>${t('Internet, billing, security and more. A setup that fits your business, your budget, and your ambition.','इंटरनेट, बिलिंग और सुरक्षा। आपके व्यवसाय और बजट के हिसाब से, एक आसान प्लान।')}</p><button class="button" data-action="${hasPlan?'goto':'start'}" data-value="${isActive?'orders':hasPlan?'bundle':''}">${isActive?t('View your business','अपना व्यवसाय देखें'):hasPlan?t('Continue your setup','अपना प्लान जारी रखें'):t('Find my business setup','मेरा बिज़नेस प्लान बनाएँ')}${icon('arrow')}</button><div class="hero-foot">${icon('shield')}${t('No pressure. No payment to explore.','बिना दबाव। प्लान देखने का कोई शुल्क नहीं।')}</div></div><img class="hero-art" src="/launchpad.svg" alt="A neighbourhood shop connected to a clear budget and digital tools"></section>
<div class="journey-strip" aria-label="Your launch journey">${[['advisor',t('Tell us your goals','अपने लक्ष्य बताएँ'),t('A few simple questions','कुछ आसान सवाल')],['bundle',t('Make it your own','अपना प्लान बनाएँ'),t('One transparent quote','सभी कीमतें स्पष्ट')],['verify',t('Verify your business','व्यवसाय सत्यापित करें'),t('Your data, in your control','डेटा आपके नियंत्रण में')],['orders',t('We’ll get you going','शुरुआत करें'),t('Every next step, visible','हर कदम की जानकारी')]].map(([id,label,sub],i)=>`<button class="journey-step ${i===stage?'current':i<stage?'complete':''}" data-action="goto" data-value="${id}"><span class="journey-number">${i<stage?icon('check'):'0'+(i+1)}</span><span><b>${label}</b><small>${sub}</small></span></button>`).join('')}</div>
<div class="section-heading"><div><h2>${t('Built around your business.','आपके व्यवसाय के हिसाब से।')}</h2><p>${t('Different businesses need different things. What does yours look like?','हर व्यवसाय की ज़रूरत अलग है। आपका व्यवसाय कैसा है?')}</p></div><span class="muted">${t('A good place to start','यहाँ से शुरुआत करें')}</span></div>
<div class="business-grid">${businessTypes.map(b=>`<button class="business-card" data-action="business" data-value="${b.id}"><span class="icon-tile ${b.color}">${icon(b.icon)}</span><span class="corner-arrow">${icon('up')}</span><h3>${t(b.name,b.hi)}</h3><p>${b.desc}</p></button>`).join('')}</div>
<div class="two-column"><section class="panel"><div class="panel-head"><h2>${t('Start small. Grow at your pace.','छोटे कदम। अपनी रफ़्तार।')}</h2><span class="badge green">${t('Budget first','बजट पहले')}</span></div><div class="budget-story"><div class="mini-chart" aria-hidden="true"><span style="height:28px"></span><span style="height:47px"></span><span style="height:70px"></span></div><div><h3>${t('The essentials today.<br>The possibilities, whenever you’re ready.','ज़रूरी सेवाएँ आज।<br>अगला कदम, जब आप तैयार हों।')}</h3><p>${t('We separate what you need now from what can wait.<br>Because a bigger bundle isn’t always a better one.','जो अभी ज़रूरी है, बस उसी से शुरुआत करें। बाकी बाद में जोड़ सकते हैं।')}</p><button class="text-button" data-action="start">${t('Build within my budget','मेरे बजट में प्लान बनाएँ')}${icon('arrow')}</button></div></div></section><section class="panel"><div class="panel-head"><h2>${t('Clarity makes a difference.','स्पष्टता से फ़र्क पड़ता है।')}</h2><span class="badge gray">${t('From the case data','केस के डेटा से')}</span></div><div class="insight-number">206<small>${t('businesses','व्यवसाय')}</small></div><div class="insight-bottom"><p>${t('left because the quote was too complex.<br>We think you deserve a clearer answer.','जटिल कोटेशन की वजह से आगे नहीं बढ़े।<br>आप बेहतर जवाब के हक़दार हैं।')}</p><button class="text-button" data-action="goto" data-value="impact">${t('See the evidence','प्रमाण देखें')}${icon('up')}</button></div></section></div>`}
function advisor(){if(!Object.keys(wizard).length)wizard={...S.profile,language};const next=wizardEdit||(!wizard.segment?'segment':!wizard.employees?'employees':!wizard.needs?.length?'needs':!wizard.budget?'budget':'ready');const steps={segment:0,employees:1,needs:2,budget:3,ready:4};const btype=businessTypes.find(b=>b.id===wizard.segment);let question={segment:t('Let’s start with you. What kind of business do you run?','शुरुआत आपसे करें। आपका व्यवसाय किस तरह का है?'),employees:t('A little about your team and locations helps me size things correctly.','टीम और जगहों की जानकारी से सही प्लान बनाने में मदद मिलेगी।'),needs:t('What would make your working day better? Choose what matters most.','काम आसान बनाने के लिए आपको क्या चाहिए? ज़रूरी विकल्प चुनें।'),budget:t('One last thing: what monthly budget feels comfortable? We’ll include GST.','आखिरी सवाल: GST सहित आपका मासिक बजट कितना है?'),ready:t('That gives us a good starting point. I’ll prioritise the essentials and keep the rest for later.','अच्छा, अब शुरुआत कर सकते हैं। पहले ज़रूरी सेवाएँ और बाकी बाद के लिए रखेंगे।')}[next];
let form='';if(next==='segment')form=`<div class="question-title">${t('My business is…','मेरा व्यवसाय है…')}</div><div class="advisor-options">${businessTypes.map(b=>`<button class="advisor-option" data-action="choose-business" data-value="${b.id}">${icon(b.icon)}<span>${t(b.name,b.hi)}</span>${icon('arrow','checkmark')}</button>`).join('')}</div>`;
if(next==='employees')form=`<form id="team-form"><div class="question-title">${t('Small details. A better fit.','छोटी जानकारी। बेहतर प्लान।')}</div><div class="form-grid"><label class="field">${t('People in your team','टीम में लोग')}<input name="employees" type="number" min="1" max="10000" value="${wizard.employees||5}" required></label><label class="field">${t('Business locations','व्यवसाय की जगहें')}<input name="sites" type="number" min="1" max="100" value="${wizard.sites||1}" required></label><label class="field">${t('Devices / email users to cover','डिवाइस / ईमेल यूज़र')}<input name="seats" type="number" min="1" max="1000" value="${wizard.seats||3}" required><small>${t('Used to size device security and email.','डिवाइस सुरक्षा और ईमेल की संख्या।')}</small></label><label class="field">${t('City','शहर')}<select name="city"><option value="Pune|1">Pune · Tier 1</option><option value="Mumbai|1">Mumbai · Tier 1</option><option value="Delhi|1">Delhi · Tier 1</option><option value="Bengaluru|1">Bengaluru · Tier 1</option><option value="Chennai|1">Chennai · Tier 1</option><option value="Hyderabad|1">Hyderabad · Tier 1</option><option value="Jaipur|2">Jaipur · Tier 2</option><option value="Indore|2">Indore · Tier 2</option><option value="Kochi|2">Kochi · Tier 2</option><option value="Other tier 1 city|1">Other tier 1 city</option><option value="Other tier 2 city|2">Other tier 2 city</option></select></label></div><button class="button" type="submit">${t('That’s my team','यही मेरी टीम है')}${icon('arrow')}</button></form>`;
if(next==='needs')form=`<div class="question-title">${t('I’d like to…','मैं चाहता/चाहती हूँ…')}</div><div class="advisor-options">${goals.map(g=>`<button class="advisor-option ${selectedGoals.includes(g.id)?'selected':''}" data-action="goal" data-value="${g.id}" aria-pressed="${selectedGoals.includes(g.id)}">${icon(g.icon)}<span>${t(g.name,g.hi)}</span>${selectedGoals.includes(g.id)?icon('check','checkmark'):''}</button>`).join('')}</div><button class="button" data-action="confirm-goals">${t('These are my priorities','यही मेरी प्राथमिकताएँ हैं')}${icon('arrow')}</button>`;
if(next==='budget')form=`<form id="budget-form"><div class="question-title">${t('Monthly budget, including estimated GST','मासिक बजट, अनुमानित GST सहित')}</div><div class="budget-input-line"><div class="budget-value" id="budget-display">${money(wizard.budget||3000)}</div><label class="field">Exact budget<input type="number" name="budget" id="budget-number" min="1" max="10000000" value="${wizard.budget||3000}" required aria-label="Exact monthly budget"></label></div><label class="field bottom-space"><span class="hidden">Monthly budget</span><input type="range" id="budget-slider" name="budget-range" min="1000" max="50000" step="500" value="${Math.min(50000,wizard.budget||3000)}" aria-label="Monthly budget"><span class="range-labels"><span>₹1,000</span><span>₹50,000</span></span></label><div class="form-grid"><label class="field full">${t('Current internet setup','अभी का इंटरनेट')}<select name="fibre"><option value="available">${t('Fibre is available / not sure yet','फ़ाइबर उपलब्ध है / अभी पता नहीं')}</option><option value="unavailable">${t('No fibre at my location','मेरी जगह पर फ़ाइबर नहीं है')}</option><option value="existing">${t('I already have internet','मेरे पास पहले से इंटरनेट है')}</option></select><small>${t('Availability must be confirmed by a site check.','उपलब्धता की पुष्टि साइट जाँच से होगी।')}</small></label><label class="field">${t('Current spend, incl. GST (optional)','अभी का मासिक खर्च (वैकल्पिक)')}<input name="current_spend" type="number" min="0" max="10000000" value="${wizard.current_spend||0}"></label><label class="field">${t('Do you have a GSTIN?','क्या आपके पास GSTIN है?')}<select name="has_gstin"><option value="false">${t('No / not sure','नहीं / पता नहीं')}</option><option value="true">${t('Yes, I’ll verify it later','हाँ, बाद में सत्यापित करूँगा')}</option></select></label></div><button class="button" type="submit">${t('Find my best fit','मेरे लिए सही प्लान चुनें')}${icon('spark')}</button></form>`;
if(next==='ready')form=`<div class="bottom-space">${[['segment','Business',businessName(wizard)],['employees','Team & locations',(wizard.employees||5)+' people · '+(wizard.sites||1)+' location(s)'],['needs','Priorities',(wizard.needs||[]).map(k=>goals.find(g=>g.id===k)?.name).join(', ')],['budget','Monthly budget',money(wizard.budget)]].map(([key,label,value])=>`<div class="summary-row"><span>${label}</span><b>${esc(value)} <button class="text-button" style="margin-left:10px;font-size:10px" data-action="edit-field" data-value="${key}">Edit</button></b></div>`).join('')}</div><div class="pill-row bottom-space"><span class="badge">${esc(businessName(wizard))}</span><span class="badge gray">${wizard.employees} ${t('people','लोग')} · ${wizard.sites||1} ${t('location(s)','जगह')} · ${wizard.seats||wizard.employees} seats</span><span class="badge green">${money(wizard.budget)} ${t('budget','बजट')}</span></div><button class="button" data-action="build-plan">${t('Build my launch plan','मेरा प्लान बनाएँ')}${icon('spark')}</button> <button class="text-button" data-action="restart-advisor">${t('Start again','फिर से शुरू करें')}</button>`;
if(next==='employees'&&wizard.city)form=form.replace(`value="${esc(wizard.city)}|${wizard.tier}"`,`value="${esc(wizard.city)}|${wizard.tier}" selected`);
if(next==='budget'){form=form.replace(`value="${wizard.fibre||'available'}"`,`value="${wizard.fibre||'available'}" selected`);if(wizard.has_gstin)form=form.replace('value="true"','value="true" selected')}
return `${stepper('advisor')}<div class="page-heading"><div class="screen-intro"><h1>${t('A good plan starts with a conversation.','एक अच्छे प्लान की शुरुआत बातचीत से।')}</h1><p>${t('Tell us what you do. We’ll help you choose what’s worth paying for.','अपने व्यवसाय के बारे में बताएँ। हम सही सेवाएँ चुनने में मदद करेंगे।')}</p></div><button class="button secondary small-button" data-action="scenarios">${t('Try an example','उदाहरण देखें')}${icon('spark')}</button></div><div class="advisor-layout"><section class="panel advisor-card"><div class="advisor-header"><div class="advisor-avatar">✦</div><div><h3>${t('Your business advisor','आपका बिज़नेस सलाहकार')}</h3><p><span class="online-dot"></span>${capabilities.ai?t('AI explanations · catalogue-checked plans','AI सलाह · कैटलॉग से सत्यापित प्लान'):t('Guided discovery · catalogue-checked plans','आसान सवाल · कैटलॉग से सत्यापित प्लान')}</p></div><button class="icon-button" style="margin-left:auto" data-action="listen" aria-label="Listen to the advisor">${icon('listen')}</button></div><div class="advisor-body">${messages.slice(-2).map(m=>`<div class="chat-message user"><div class="chat-bubble">${esc(m)}</div></div>`).join('')}<div class="chat-message"><span class="chat-avatar">✦</span><div class="chat-bubble" id="advisor-question">${question}</div></div>${form}</div><form class="advisor-input" id="chat-form"><div class="chat-composer"><textarea name="message" aria-label="Tell the advisor about your business" placeholder="${t('Or tell me in your own words: I run a clinic with 8 staff…','या अपने शब्दों में बताएँ: मेरा क्लिनिक है, 8 लोग काम करते हैं…')}" maxlength="1500" required></textarea><button class="icon-button" type="submit" aria-label="Send message">${icon('send')}</button></div><p>${t('You stay in control. No personal documents needed to explore.','नियंत्रण आपके पास है। प्लान देखने के लिए निजी दस्तावेज़ नहीं चाहिए।')}</p></form></section><aside class="panel profile-summary"><div class="eyebrow">${t('YOUR BUSINESS, AT A GLANCE','आपका व्यवसाय, एक नज़र में')}</div><h3>${btype?t(btype.name,btype.hi):t('Let’s get to know you.','आपको जानें।')}</h3><div class="mini-progress"><span style="width:${steps[next]*25}%"></span></div><span class="muted small">${steps[next]} ${t('of 4 details covered','/ 4 जानकारी मिल गई')}</span>${!wizard.segment?`<p class="summary-empty">${t('Your plan takes shape as we learn what matters to your business.','आपकी ज़रूरतों के हिसाब से आपका प्लान तैयार होगा।')}</p>`:''}${wizard.employees?`<div class="summary-row"><span>${t('Team','टीम')}</span><b>${wizard.employees} ${t('people','लोग')}</b></div><div class="summary-row"><span>${t('Locations','जगह')}</span><b>${wizard.sites||1} · ${esc(wizard.city||'To confirm')}</b></div>`:''}${wizard.needs?.length?`<div class="summary-row"><span>${t('Priorities','प्राथमिकताएँ')}</span><b>${wizard.needs.map(k=>goals.find(g=>g.id===k)?.name).map(esc).join('<br>')}</b></div>`:''}${wizard.budget?`<div class="summary-row"><span>${t('Monthly budget','मासिक बजट')}</span><b>${money(wizard.budget)}</b></div>`:''}<div class="advisor-promise">${icon('heart')}<span>${t('A bigger bill is not our goal.<br>A better fit for you is.','हमारा लक्ष्य बड़ा बिल नहीं,<br>आपके लिए सही प्लान है।')}</span></div></aside></div>`}
function quoteCard(q,action=true){const p=S.profile;return `<aside class="panel quote-card"><div class="eyebrow">${t('ONE PLAN. EVERY RUPEE VISIBLE.','एक प्लान। हर रुपया स्पष्ट।')}</div><h3>${t('Your monthly commitment','आपका मासिक खर्च')}</h3><div class="quote-price">${money(q.total,2)}<small> / ${t('month','माह')}</small></div><p class="quote-subtitle">${t('Including estimated 18% GST','अनुमानित 18% GST सहित')}</p><div class="quote-line"><span>${t('Services','सेवाएँ')}</span><strong>${money(q.subtotal,2)}</strong></div><div class="quote-line"><span>GST (18%)</span><strong>${money(q.tax,2)}</strong></div><div class="quote-line total"><span>${t('Monthly total','मासिक कुल')}</span><strong>${money(q.total,2)}</strong></div><div class="quote-divider"></div><div class="quote-line"><span>${t('One-time setup + GST','एक बार सेटअप + GST')}</span><strong>${money(q.setup_total,2)}</strong></div><div class="quote-line"><span>${t('First invoice estimate','पहले बिल का अनुमान')}</span><strong>${money(q.first_invoice,2)}</strong></div><div class="quote-line"><span>${t('Longest minimum term','सबसे लंबी न्यूनतम अवधि')}</span><strong>${q.contract} ${t('months','महीने')}</strong></div><div class="budget-meter ${q.budget_gap?'over':''}"><div class="budget-meter-top"><span>${t('Your monthly budget','आपका मासिक बजट')}</span><strong>${money(p.budget)}</strong></div><div class="meter-track"><span style="width:${Math.min(100,100*q.total/p.budget)}%"></span></div><p>${q.budget_gap?t(`${money(q.budget_gap,2)} above your budget. Remove an add-on or adjust your goals.`,`${money(q.budget_gap,2)} बजट से ज़्यादा। कोई सेवा हटाएँ या लक्ष्य बदलें।`):t(`${money(q.headroom,2)} of breathing room. Add more only when you need it.`,`${money(q.headroom,2)} बजट में बाकी। ज़रूरत होने पर ही नई सेवाएँ जोड़ें।`)}</p></div>${q.gst_pending?`<p class="savings-note">${icon('info')} ${t('Some services require an active GSTIN before checkout.','कुछ सेवाओं के लिए सक्रिय GSTIN ज़रूरी है।')}</p>`:''}${p.current_spend?`<p class="savings-note">${t('You told us you currently spend','आपने वर्तमान खर्च बताया')} ${money(p.current_spend)}/${t('month','माह')}. ${q.total<p.current_spend?t(`This estimate is ${money(p.current_spend-q.total,2)} lower.`,`${money(p.current_spend-q.total,2)} का अंतर है।`):t('Review the added capability against the higher cost.','अतिरिक्त सेवाओं के बदले बढ़ा खर्च जाँचें।')} ${t('Service scope may differ.','सेवाओं का दायरा अलग हो सकता है।')}</p>`:''}${action?`<button class="button full" data-action="goto" data-value="verify">${t('Continue to verification','सत्यापन जारी रखें')}${icon('arrow')}</button><p class="quote-assurance">${icon('lock')}${t('No payment taken at this step','इस कदम पर कोई भुगतान नहीं')}</p>`:''}<button class="text-button" style="margin-top:17px;width:100%;justify-content:center;font-size:9px" data-action="download">${icon('download')}${t('Download this quote','कोटेशन डाउनलोड करें')}</button><p class="quote-note">${t('Catalogue starting rates. Term and setup fees are shown for each service. Installation estimates start after KYC and site feasibility. Final serviceability and commercial approval are required.','कैटलॉग की शुरुआती दरें। हर सेवा की अवधि और सेटअप शुल्क स्पष्ट हैं। KYC और साइट जाँच के बाद स्थापना का अनुमान लागू होगा।')}</p></aside>`}
function bundle(){if(!Q)return `${stepper('bundle')}<section class="panel empty-state"><div class="icon-tile">${icon('box')}</div><h2>${t('Let’s make it a good fit.','आपके लिए सही प्लान बनाएँ।')}</h2><p>${t('A short conversation helps us build a plan around your goals and budget.','कुछ आसान सवालों से आपके लक्ष्य और बजट के हिसाब से प्लान बनेगा।')}</p><button class="button" data-action="start">${t('Meet your advisor','सलाहकार से मिलें')}${icon('arrow')}</button></section>`;
const reasons=S.plan?.reasons||[];const later=S.plan?.later||[];return `${stepper('bundle')}<div class="page-heading"><div class="screen-intro"><h1>${t('Only what your business needs.','बस वही, जिसकी आपके व्यवसाय को ज़रूरत है।')}</h1><p>${t('A starting point, not a sales pitch. Make it yours before moving on.','एक सही शुरुआत। आगे बढ़ने से पहले अपने हिसाब से बदलाव करें।')}</p></div><button class="text-button" data-action="goto" data-value="advisor">${t('Edit my goals','लक्ष्य बदलें')}${icon('up')}</button></div><div class="pill-row"><span class="badge">${icon('shop')}${esc(businessName(S.profile))}</span><span class="badge gray">${S.profile.employees} ${t('people','लोग')} · ${S.profile.sites} ${t('location(s)','जगह')}</span><span class="badge ${Q.budget_gap?'amber':'green'}">${icon(Q.budget_gap?'alert':'check')}${Q.budget_gap?t('Review budget gap','बजट का अंतर देखें'):t('Inside your budget','आपके बजट में')}</span></div><div class="layout-split"><div class="stack"><div class="plan-intro">${icon('spark')}<div><h3>${t('Here’s the thinking.','इस प्लान के पीछे की सोच।')}</h3><p>${esc(quoteMode==='recommended'?(S.plan?.explanation||'Every service is priced and validated against the catalogue.'):t(`You’ve tailored this plan to ${Q.items.length} service(s). Quantities, eligibility and dependencies have been checked. Review the updated budget and first invoice before continuing.`,`आपने ${Q.items.length} सेवाओं का प्लान चुना है। संख्या, पात्रता और निर्भरताएँ जाँची गई हैं। आगे बढ़ने से पहले नया बजट और पहला बिल देखें।`))}</p></div></div><div><div class="plan-toolbar"><h3>${t('Your launch plan','आपका शुरुआती प्लान')} <span class="muted small">(${Q.items.length})</span></h3><div class="segmented"><button data-action="recommended" class="${quoteMode==='recommended'?'active':''}">${t('Recommended','सुझाया गया')}</button><button data-action="lean" class="${quoteMode==='lean'?'active':''}">${t('Essentials only','सिर्फ ज़रूरी')}</button></div></div><div class="service-list">${Q.items.map(item=>{const p=CAT.find(p=>p.product_id===item.id),r=reasons.find(r=>r.id===item.id);return `<article class="service-row"><div class="icon-tile ${colorFor(p)}">${icon(productIcon(p))}</div><div class="service-main"><h3>${esc(item.name)}</h3><p>${esc(r?.text||p.description)}</p><div class="service-meta"><span>${money(item.rate)} ${esc(item.unit)} / month</span><span>${item.contract}-month minimum</span><span>${item.setup?money(item.setup)+' setup (excl. GST)':'No setup fee'}</span></div></div><div class="service-right"><strong>${money(item.monthly)}</strong><small>/ ${t('month','माह')} + GST</small><div class="quantity-control"><button data-action="quantity" data-value="${item.id}" data-delta="-1" aria-label="Decrease ${esc(item.name)} quantity">−</button><span aria-label="Quantity">${item.quantity}</span><button data-action="quantity" data-value="${item.id}" data-delta="1" aria-label="Increase ${esc(item.name)} quantity">+</button></div><button class="remove-service" data-action="remove" data-value="${item.id}">${t('Remove','हटाएँ')}</button></div></article>`}).join('')}</div><button class="add-service" data-action="catalogue">${icon('plus')}${t('Explore services & add-ons','सेवाएँ और ऐड-ऑन देखें')}</button></div>${later.length?`<section class="later-card"><span class="badge gray" style="margin-bottom:10px">${t('PHASE TWO · WHEN YOU’RE READY','दूसरा चरण · जब आप तैयार हों')}</span><h3>${t('Good ideas. Just not all at once.','अच्छे विकल्प। पर सब एक साथ नहीं।')}</h3><p>${t('These did not make the starting plan. Here’s why.','इन्हें शुरुआती प्लान में शामिल नहीं किया। कारण यहाँ हैं।')}</p>${later.map(p=>`<div class="later-row">${icon('clock')}<div><h4>${esc(p.name)}</h4><p>${esc(p.reason)}</p></div><strong>${money(p.monthly)}<span class="muted small"> /mo</span></strong></div>`).join('')}</section>`:''}<div class="trust-note">${icon('shield')}<span>${t('Your plan is checked against product eligibility and dependencies. If a change needs another service, we’ll explain it before you commit.','हर सेवा की पात्रता और निर्भरता की जाँच होती है। किसी बदलाव के लिए दूसरी सेवा चाहिए तो पहले बताएँगे।')}</span></div></div>${quoteCard(Q)}</div>`}
function checkRows(checks){return checks.map(c=>`<div class="check-row ${c.status}">${icon(c.status==='pass'?'circlecheck':c.status==='error'?'alert':'clock')}<div><h4>${esc(c.title)}</h4><p>${esc(c.detail)}</p></div></div>`).join('')}
function verify(){if(!Q)return bundle();const reg=S.registry;const docs=S.documents||{};return `${stepper('verify')}<div class="screen-intro"><h1>${t('A little trust goes a long way.','भरोसे की शुरुआत, सही जानकारी से।')}</h1><p>${t('Verify your business once. We’ll tell you what checks out, and help with what doesn’t.','व्यवसाय सत्यापित करें। क्या सही है और कहाँ मदद चाहिए, सब स्पष्ट बताएँगे।')}</p></div><div class="layout-split"><div class="stack"><section class="panel consent-card"><div class="panel-head no-margin"><h3>${t('Your permission comes first.','पहले आपकी अनुमति।')}</h3>${icon('lock')}</div><p>${t('We use your registration and document details only to verify this demo order. Images are processed on this computer and deleted immediately after extraction. Extracted details expire after 24 hours of inactivity.','जानकारी का उपयोग सिर्फ इस डेमो ऑर्डर के सत्यापन के लिए होगा। तस्वीरों को इसी कंप्यूटर पर पढ़कर तुरंत हटा दिया जाएगा। निकाली गई जानकारी 24 घंटे की निष्क्रियता के बाद मिटाई जाएगी।')}</p><label class="checkbox-label"><input type="checkbox" id="consent" ${S.consent?'checked':''} data-change="consent"><span>${t('I agree to registration and document checks for this demo order.','मैं इस डेमो ऑर्डर के लिए पंजीकरण और दस्तावेज़ जाँच की अनुमति देता/देती हूँ।')} <button class="text-button" style="font-size:10px" data-action="privacy">${t('See how my data is handled','डेटा का उपयोग जानें')}</button></span></label></section><section class="panel"><div class="registry-tabs"><div><h2>${t('Your business registration','व्यवसाय का पंजीकरण')}</h2><p class="muted small" style="font-size:9px;margin-top:4px">${t('One verified registration gets you started.','एक सत्यापित पंजीकरण से शुरुआत करें।')}</p></div><div class="segmented"><button data-action="registry-kind" data-value="gst" class="${registryKind==='gst'?'active':''}">GSTIN</button><button data-action="registry-kind" data-value="udyam" class="${registryKind==='udyam'?'active':''}">Udyam</button></div></div><form id="registry-form" class="registry-form"><label class="field">${registryKind==='gst'?'GST identification number':'Udyam registration number'}<input type="password" name="identifier" autocomplete="off" placeholder="${registryKind==='gst'?'15-character GSTIN':'UDYAM-XX-00-0000000'}" maxlength="25" required></label><button class="button" type="submit">${t('Verify','सत्यापित करें')}${icon('shield')}</button></form>${reg?`<div class="registry-result ${!['Active','Registered'].includes(reg.status)?'error':''}">${icon(['Active','Registered'].includes(reg.status)?'circlecheck':'alert')}<div><strong>${esc(reg.name)}</strong><p>${esc(reg.masked)} · ${esc(reg.status)}</p></div></div>`:''}<p class="source-label">${t('Connected to the supplied mock registry. No live government request is made.','दिए गए नकली रजिस्टर से जाँच। कोई सरकारी API कॉल नहीं।')} <button class="text-button" style="font-size:9px" data-action="demo-registry">${t('Try the K02 demo business','K02 डेमो व्यवसाय देखें')}${icon('arrow')}</button></p></section><section class="panel"><div class="panel-head"><div><h2>${t('Documents, without the guesswork.','दस्तावेज़, बिना उलझन के।')}</h2><p>${t('Upload a clear image. We’ll extract and check the details.','साफ़ तस्वीर डालें। हम जानकारी पढ़कर जाँच करेंगे।')}</p></div><label class="specimen-select">Demo<select id="applicant" aria-label="Demo applicant">${Array.from({length:12},(_,i)=>'K'+String(i+1).padStart(2,'0')).map(k=>`<option ${currentApplicant===k?'selected':''}>${k}</option>`).join('')}</select></label></div>${[['gst','Registration certificate','GST / Udyam certificate · optional with a verified registry','doc'],['address','Business address proof','A utility bill issued within the fixture’s 90-day window','office'],['signatory','Authorised signatory ID','Name, business and ID validity checks','people']].map(([kind,label,desc,i])=>{let actual=kind==='gst'&&reg?.kind==='udyam'?'udyam':kind;let d=docs[actual];let status=d?d.checks.some(c=>c.status==='error')?'red':d.checks.some(c=>c.status==='warning')?'amber':'green':'gray';return `<article class="document-row"><div class="icon-tile ${d?'green':''}">${icon(i)}</div><div class="document-main"><h4>${label} ${d?`<span class="badge ${status}" style="margin-left:5px">${status==='green'?'Read & checked':'Needs attention'}</span>`:''}</h4><p>${desc}</p>${d?`<div class="ocr-fields">${Object.entries(d.fields).map(([k,v])=>`<div>${esc(k.replaceAll('_',' '))}: <b>${esc(v)}</b></div>`).join('')}${d.identifier?`<div>Registration: <b>${esc(d.identifier)}</b></div>`:''}</div><div class="ocr-engine">${esc(d.engine)} · OCR ${Math.round(d.confidence*100)}% recognition confidence · authenticity not inferred</div>`:''}<div class="document-actions"><label class="button secondary small-button file-button">${icon('upload')}${d?t('Replace image','तस्वीर बदलें'):t('Upload image','तस्वीर डालें')}<input type="file" accept="image/png,image/jpeg" data-upload="${actual}" aria-label="Upload ${label}"></label><button class="text-button" data-action="specimen" data-value="${actual}">${t('Use','चुनें')} ${currentApplicant} ${t('specimen','नमूना')}${icon('arrow')}</button></div></div></article>`}).join('')}<p class="privacy-detail">${icon('lock')}${t('PNG or JPEG, up to 8 MB. Files are never sent to an external OCR service.','PNG या JPEG, अधिकतम 8 MB। तस्वीर किसी बाहरी OCR सेवा को नहीं भेजी जाती।')}</p></section><div class="trust-note">${icon('info')}<span>${t('This dataset uses 15 Jul 2026 as its reference date for document freshness. Automated checks help a partner review the evidence; they do not establish document authenticity.','दस्तावेज़ों की तारीख की जाँच 15 जुलाई 2026 से होती है। स्वचालित जाँच पार्टनर की समीक्षा में मदद करती है; प्रामाणिकता की गारंटी नहीं देती।')}</span></div></div><aside class="panel quote-card verification-summary"><div class="eyebrow">${t('NO MYSTERY. NO SILENT REJECTIONS.','हर जाँच का स्पष्ट कारण।')}</div><h2>${t('Here’s where you stand.','अभी आपकी स्थिति।')}</h2><span class="badge ${S.kyc.state==='ready'?'green':S.kyc.state==='attention'?'red':'amber'}">${esc(S.kyc.label)}</span><div class="checklist">${checkRows(S.kyc.checks)}</div><div class="quote-divider"></div><div class="quote-line"><span>${t('Your plan, incl. GST','आपका प्लान, GST सहित')}</span><strong>${money(Q.total,2)} /mo</strong></div><button class="button full" data-action="checkout">${t('Review & reserve plan','प्लान देखें और आरक्षित करें')}${icon('arrow')}</button><p class="quote-note">${t('You can reserve while documents are reviewed. Activation remains blocked until verification is approved. No real charge or contract is created.','दस्तावेज़ समीक्षा के दौरान प्लान आरक्षित कर सकते हैं। सत्यापन के बाद ही सक्रिय होगा। कोई वास्तविक शुल्क या अनुबंध नहीं।')}</p><button class="text-button" style="font-size:10px;margin-top:16px" data-action="help">${t('Help me resolve a check','जाँच में मेरी मदद करें')}${icon('up')}</button></aside></div>`}
function orders(){const all=S.orders||[];const order=all.find(o=>o.id===selectedOrder)||all[0];if(!order)return `${stepper('orders')}<section class="panel empty-state"><div class="icon-tile">${icon('route')}</div><h2>${t('Your next chapter will show up here.','आपकी अगली शुरुआत यहाँ दिखेगी।')}</h2><p>${t('Once you reserve a plan, every milestone and next step lives in one place. No chasing, no guessing.','प्लान आरक्षित करने के बाद हर कदम की जानकारी यहाँ मिलेगी।')}</p><button class="button" data-action="goto" data-value="${Q?'verify':'advisor'}">${Q?t('Continue my setup','सेटअप जारी रखें'):t('Build my plan','मेरा प्लान बनाएँ')}${icon('arrow')}</button></section>`;
const stages=['review','verified','scheduled','active'];const index=stages.indexOf(order.status);const current={review:['Your plan is in good hands.','A partner needs to review your documents before anything is activated.'],verified:['Verified. Ready for the next step.','Your documents have been reviewed. The demo operator can now schedule installation.'],scheduled:['A date for your next chapter.','Installation is scheduled for '+new Date(order.installation+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})+'.'],active:['You’re ready for more.','The local demo operator has recorded service activation. This is a simulated provider workflow.']}[order.status];return `${stepper('orders')}${pageHeading(t('Every next step, in plain sight.','हर अगला कदम, स्पष्ट नज़र में।'),t('One place to see what’s done, what’s next, and who can help.','क्या पूरा हुआ, आगे क्या होगा और कौन मदद करेगा—एक जगह।'),`<button class="button secondary small-button" data-action="refresh-order">${t('Refresh status','स्थिति अपडेट करें')}${icon('route')}</button>`)}<section class="tracker-hero"><div><div class="eyebrow">${esc(order.id)} · DEMO ORDER</div><h2>${current[0]}</h2><p>${esc(current[1])}</p></div><div class="icon-tile">${icon(order.status==='active'?'circlecheck':'route')}</div></section>${all.length>1?`<label class="field bottom-space">Order<select id="order-select">${all.map(o=>`<option value="${o.id}" ${o.id===order.id?'selected':''}>${o.id} · ${esc(o.status)}</option>`).join('')}</select></label>`:''}<section class="panel bottom-space"><h3>${esc(order.name)}</h3><p class="muted small" style="font-size:9px;margin-top:5px">${esc(order.city)} · ${order.quote.items.length} services · ${money(order.quote.total,2)}/month incl. GST</p><div class="tracker-progress">${[['review','Plan reserved'],['verified','Business verified'],['scheduled','Installation booked'],['active','You’re live']].map(([key,name],i)=>`<div class="tracker-node ${i<index?'completed':''} ${i===index?'current':''}"><span>${i<index?icon('check'):i+1}</span><b>${name}</b></div>`).join('')}</div></section><div class="two-column"><section class="panel"><div class="panel-head"><h2>${t('Your journey so far','अभी तक का सफ़र')}</h2><span class="badge gray">${t('Recorded events','दर्ज किए गए कदम')}</span></div>${[...order.events].reverse().map(event=>`<div class="event-row"><span class="event-dot"></span><div><h4>${esc(event.title)}</h4><p>${esc(event.detail)}</p><time>${new Date(event.at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}${event.actor?' · '+esc(event.actor):''}</time></div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>${t('What happens next?','आगे क्या होगा?')}</h2>${icon('spark')}</div>${order.status==='review'?`<p class="check-summary">${t('Your registration is checked. A partner will review the address and signatory evidence before approving the next step.','पंजीकरण जाँच लिया गया है। पार्टनर पते और हस्ताक्षरकर्ता के दस्तावेज़ की समीक्षा करेगा।')}</p><div class="checklist">${checkRows(S.kyc.checks.filter(c=>c.status!=='pass').slice(0,3))}</div><button class="button soft small-button" data-action="goto" data-value="verify">${t('Review my documents','मेरे दस्तावेज़ देखें')}${icon('arrow')}</button>`:`<p class="check-summary">${esc(current[1])} ${t('You can ask for assistance without starting over.','आप दोबारा शुरू किए बिना मदद माँग सकते हैं।')}</p>`}<div class="quote-divider"></div><button class="text-button" data-action="help">${t('Ask a partner for help','पार्टनर से मदद माँगें')}${icon('up')}</button><p class="quote-note">${t('For the demo: progress this order from Partner desk. Every change records an operator note. No live installation is ordered.','डेमो में: पार्टनर डेस्क से ऑर्डर आगे बढ़ाएँ। हर बदलाव के साथ नोट दर्ज होगा। कोई वास्तविक स्थापना नहीं होगी।')}</p><button class="text-button" style="font-size:9px;margin-top:10px" data-action="open-operations">${t('Open demo operations','डेमो ऑपरेशन्स खोलें')}${icon('arrow')}</button></section></div>`}
async function loadAnalytics(){try{analyticsData=await api('analytics');if(route()==='partner')render()}catch(e){toast(e.message,true)}}
function partner(){if(!analyticsData)return `${pageHeading('A good partner makes the difference.','Loading the supplied lead data…')}<div class="loading-screen"><span class="spinner"></span></div>`;const a=analyticsData;return `${pageHeading(t('Be there when it matters.','ज़रूरत के समय, सही मदद।'),t('A workspace for helping owners move forward—not making them start again.','व्यवसाय मालिकों को अगला कदम लेने में मदद करें।'),`<span class="badge gray">LOCAL DEMO OPERATOR</span>`)}<div class="segmented"><button class="${partnerTab==='leads'?'active':''}" data-action="partner-tab" data-value="leads">${t('Acquisition insights','अधिग्रहण डेटा')}</button><button class="${partnerTab==='orders'?'active':''}" data-action="partner-tab" data-value="orders">${t('Orders & handoffs','ऑर्डर और सहायता')} (${a.orders.length+a.callbacks.length})</button></div>${partnerTab==='orders'?workspaceOperations(a):`<div class="metric-grid">${[['Lead → activation',a.conversion+'%','368 of 5,000 supplied leads'],['Average activation',a.days+' days','Historical quarter · Apr–Jun 2026'],['Blended acquisition cost',money(a.cac),'All lead costs ÷ activations'],['6-month churn',a.churn+'%','Activated cohort · supplied data']].map(([label,value,note])=>`<div class="metric-card"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div><div class="chart-grid"><section class="panel"><div class="panel-head"><h2>Where momentum gets lost</h2><span class="badge gray">5,000 leads</span></div>${a.funnel.map((r,i)=>`<div class="funnel-row"><span class="funnel-label">${r.stage}</span><div class="funnel-bar"><span style="width:${r.count/50}%;background:${['#c9bee8','#bfb0e2','#b3a0db','#a48bd2','#9577c9','#8463bf'][i]}"></span></div><span class="funnel-count">${r.count.toLocaleString('en-IN')}</span><span class="funnel-rate">${i?Math.round(100*r.count/a.funnel[i-1].count)+'%':'—'}</span></div>`).join('')}<p class="chart-note">Percentages are conversion from the previous stage. Counts are cumulative, calculated from stage reached.</p></section><section class="panel"><div class="panel-head"><h2>A sharper place to start</h2>${icon('chart')}</div>${[...a.segments].sort((x,y)=>y.conversion-x.conversion).map(s=>`<div class="segment-row"><div><span>${esc(s.segment)}</span><b>${s.conversion}%</b></div><small>${s.activated} activations / ${s.leads} leads · ${money(s.cac)} blended CAC</small></div>`).join('')}<p class="chart-note">Professional offices: 11.07% conversion and the lowest observed CAC (₹10,695). A focused pilot candidate, not a prediction of future outcomes.</p></section></div><section class="panel"><div class="panel-head"><div><h2>A useful call starts with a reason.</h2><p>Late-stage leads with a clear blocker. Ranked with an explainable priority score.</p></div><span class="badge amber">${a.queue.length} callbacks to consider</span></div><div class="table-wrap"><table><thead><tr><th>Business</th><th>What’s holding them back</th><th>Priority</th><th>Next best action</th></tr></thead><tbody>${a.queue.slice(0,12).map(l=>`<tr><td><b>${esc(l.business)}</b><small>${esc(l.id)} · ${esc(l.city)}</small></td><td>${esc(l.reason)}<small>${esc(l.stage)}</small></td><td><span class="priority-dot"><i></i>${l.priority}/99</span></td><td><button class="button secondary" data-action="followup" data-value="${l.id}">${esc(l.action)}${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><p class="source-label">Priority = funnel stage × 13 + 20, with an 8-point boost for resolvable document, installation or payment blockers; capped at 99. A triage heuristic, not an activation probability. Historical data, not live customer outreach.</p></section>`}`}
function workspaceOperations(a){return `<div style="margin-top:22px" class="stack"><div class="operator-note">${icon('info')} This is a local operator simulation, scoped to this browser’s workspace. There is no production partner login or external provisioning. Status changes are deliberate, recorded actions.</div><section class="panel"><div class="panel-head"><div><h2>From reserved to ready.</h2><p>Review documents, schedule installation, then record provider completion.</p></div><span class="badge">${a.orders.length} orders</span></div>${a.orders.length?a.orders.map(o=>`<article class="operator-card"><div class="panel-head no-margin"><h3>${o.id}</h3><span class="badge ${o.status==='active'?'green':'amber'}">${esc(o.status)}</span></div><p>${esc(o.name)} · ${money(o.quote.total,2)}/month</p>${o.status==='active'?`<div class="registry-result">${icon('circlecheck')}<div><strong>Activation recorded</strong><p>The customer tracker now shows the completed demo journey.</p></div></div>`:`<form class="operator-form" data-order="${o.id}"><div class="operator-actions"><label class="field">${o.status==='review'?'Document review note':o.status==='verified'?'Installation scheduling note':'Completion / provider reference'}<input name="note" minlength="8" maxlength="500" placeholder="${o.status==='review'?'I reviewed the registration, address and signatory evidence…':o.status==='verified'?'Site checked and appointment agreed…':'Installation checked; demo service confirmed…'}" required></label>${o.status==='verified'?`<label class="field">Installation date<input name="date" type="date" min="${new Date().toLocaleDateString('en-CA')}" value="${new Date(Date.now()+86400000*o.quote.days).toLocaleDateString('en-CA')}" required></label>`:''}<button class="button small-button" type="submit">${o.status==='review'?'Approve verification':o.status==='verified'?'Schedule installation':'Record activation'}${icon('arrow')}</button></div></form>`}</article>`).join(''):`<div class="empty-inline">No orders yet. Reserve a plan to try the review workflow.</div>`}</section><section class="panel"><div class="panel-head"><div><h2>Human help, with context.</h2><p>Requests created in this workspace. No external calls or messages are sent.</p></div><span class="badge gray">${a.callbacks.length} requests</span></div>${a.callbacks.length?a.callbacks.map(c=>`<div class="operator-card"><h3>${esc(c.id)} <span class="badge amber">${esc(c.status)}</span></h3><p>${esc(c.topic)}</p><span class="muted small" style="font-size:9px">${esc(c.name)} · ${new Date(c.created).toLocaleString('en-IN')}</span></div>`).join(''):`<div class="empty-inline">The “Talk to a partner” button creates a contextual help request here.</div>`}</section></div>`}
function impact(){return `${pageHeading(t('A better journey. A measurable difference.','बेहतर सफ़र। मापने योग्य फ़र्क।'),t('The idea is simple: remove friction without removing human judgement.','विचार आसान है: उलझन कम करें, इंसानी निर्णय की जगह न लें।'))}<div class="impact-grid">${[['rupee','A plan that respects the budget','Start with the essential services. Put good-but-unaffordable ideas into phase two, with the reason shown.'],['shield','Checks that explain themselves','Local OCR and registry matching show specific issues. Uncertainty becomes a useful handoff, not a silent rejection.'],['people','A partner with context','Give the field team a reason to call and the work already completed. Keep assisted and digital acquisition on the same side.']].map(([i,title,desc])=>`<section class="panel impact-card"><span class="icon-tile">${icon(i)}</span><h3>${title}</h3><p>${desc}</p></section>`).join('')}</div><section class="panel"><div class="panel-head"><h2>A pilot worth measuring.</h2><span class="badge amber">Targets, not claimed results</span></div><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Historical baseline</th><th>Pilot hypothesis</th><th>How to measure</th></tr></thead><tbody>${[['Lead-to-activation','7.36%','12%','Same-quality lead cohorts, by segment'],['Time to activation','17.6 days (case)','Under 7 days','Lead creation → provider-confirmed activation'],['Acquisition cost','~₹15,000 (case)','Under ₹10,000','All acquisition costs ÷ activations'],['Follow-up calls','3 (case)','Under 1','Status-chasing calls per activated owner'],['Six-month churn','15.2% (56 of 368)' ,'No worse than baseline','Six-month activated cohort retention']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="tradeoff">At 5,000 comparable leads, a 12% activation rate would mean 600 activations—232 above the historical 368. That is a scenario, not a forecast. Profit still depends on gross margin, installation cost, partner commission, retention and implementation spend.</div></section><div class="two-column" style="margin-top:20px"><section class="panel"><div class="panel-head"><h2>The rollout</h2>${icon('route')}</div><div class="event-row"><span class="event-dot"></span><div><h4>Weeks 1–2 · Validate</h4><p>Test catalogue rules and KYC exceptions with partners. Establish serviceability and privacy requirements.</p></div></div><div class="event-row"><span class="event-dot"></span><div><h4>Weeks 3–6 · Pilot</h4><p>One controlled city cohort, with professional offices and micro retail. Keep manual review and joint channel attribution.</p></div></div><div class="event-row"><span class="event-dot"></span><div><h4>Weeks 7–12 · Integrate</h4><p>Provider webhooks, secure identity, document authenticity checks, payment and production retention controls.</p></div></div></section><section class="panel"><div class="panel-head"><h2>Honest about the boundaries</h2>${icon('info')}</div><p class="check-summary">This prototype runs locally with synthetic records. OCR and catalogue validation work; registry responses are mocked. Partner review and provisioning are explicitly simulated. Payments, DigiLocker, e-sign and government APIs are not connected. AI explanations are optional; the guided flow works without a key.</p><p class="source-label">Sources: supplied Airtel_SYNC_Case.pdf, product_catalogue.csv, smb_leads.csv and mock registries. Historical quarter: Apr–Jun 2026. Document fixture reference: 15 Jul 2026.</p><button class="text-button" style="margin-top:20px" data-action="goto" data-value="partner">Explore the actual data${icon('arrow')}</button></section></div>`}
function modal(title,subtitle,body,footer=''){ $('modal-content').innerHTML=`<div class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('modal').open)$('modal').showModal();}
function privacy(){modal(t('Your business. Your data.','आपका व्यवसाय। आपका डेटा।'),t('A clear explanation, before you share anything.','जानकारी देने से पहले, उपयोग की स्पष्ट जानकारी।'),`<h3>What we use</h3><p>Business size, locations, priorities and budget shape your plan. Registration numbers are checked against the supplied synthetic registry. We store only a masked number and its hash, alongside business name and status.</p><h3>What happens to documents</h3><p>PNG/JPEG images are read on this computer using local OCR. Temporary uploaded files are deleted immediately after extraction. Only extracted business/signatory names, document date and check results remain in the workspace. We do not store the original image or send it to an external OCR service.</p><h3>Retention and your control</h3><p>The workspace expires after 24 hours of inactivity; expired records are removed when the server starts and during cleanup. You can withdraw consent and delete this workspace, including orders and help requests, immediately. Local SQLite is not encrypted and backup erasure needs production controls.</p><h3>Optional AI</h3><p>If configured by the operator, a non-identifying profile and validated quote are sent to OpenAI to explain the plan. Registration identifiers and documents are excluded. The guided journey works without an API key.</p><h3>Demo boundaries</h3><p>This local prototype is not a compliance certification. Production needs secure identity, encrypted storage, provider integrations and legal review. Do not upload real identity documents into this demo.</p>`,`<button class="button secondary" data-action="close">Got it</button><button class="button danger" data-action="confirm-withdraw">Withdraw consent & delete workspace</button>`)}
function help(){modal(t('A human, when you need one.','ज़रूरत हो तो इंसानी मदद।'),t('Your plan and completed checks stay together. No need to start over.','आपका प्लान और पूरी जाँच साथ रहेंगे। दोबारा शुरुआत नहीं।'),`<form id="help-form"><label class="field">What would you like help with?<textarea name="topic" required minlength="5" maxlength="160" placeholder="I’d like help choosing the right internet connection…">${route()==='verify'?'Help me resolve my verification checks.':route()==='orders'?'Please help with the next step for '+(S.orders[0]?.id||'my order')+'.':''}</textarea></label><p>A request is saved in the local Partner desk with your current business context. This demo does not place a call or send a message.</p><button class="button" type="submit">Request a partner handoff${icon('arrow')}</button></form>`)}
function scenarios(){modal('See it through an owner’s eyes.','Choose a synthetic business story to explore a tailored plan.',`<div class="advisor-options">${[['micro','Neighbourhood kirana','₹2,500/mo · 3 people · Jaipur','shop'],['prof','A growing clinic','₹6,000/mo · 8 people · Pune','office'],['multi','Three restaurant locations','₹18,000/mo · 24 people · Mumbai','stores'],['mfg','A small manufacturing unit','₹25,000/mo · 18 people · Indore','factory']].map(([id,title,desc,i])=>`<button class="advisor-option" data-action="scenario" data-value="${id}">${icon(i)}<span>${title}<small>${desc}</small></span></button>`).join('')}</div><p>These are examples, not customer testimonials. You can edit every detail before verification.</p>`)}
function showCatalogue(){const categories=['All',...new Set(CAT.map(p=>p.category))];modal('A little more, only if you need it.','Every add-on comes from the supplied catalogue. Eligibility and dependencies are checked when you add it.',`<label class="field bottom-space">Category<select id="catalogue-category">${categories.map(c=>`<option ${c===catalogueFilter?'selected':''}>${esc(c)}</option>`).join('')}</select></label><div class="catalogue-scroll">${CAT.filter(p=>catalogueFilter==='All'||p.category===catalogueFilter).map(p=>`<article class="catalogue-item"><span class="icon-tile ${colorFor(p)}">${icon(productIcon(p))}</span><div><h3>${esc(p.product_name)}</h3><p>${esc(p.description)}</p><strong>${money(p.price_min_inr_per_month)} /month · ${esc(p.unit)}</strong><small>${p.min_contract_months}-month minimum · ${p.requires_gstin==='Y'?'Active GSTIN required · ':''}${p.one_time_setup_inr==='0'?'No setup fee':money(p.one_time_setup_inr)+' setup + GST'}</small></div><button class="button ${S.items[p.product_id]?'secondary':'soft'} small-button" data-action="add-product" data-value="${p.product_id}">${S.items[p.product_id]?'Add one':'Add'}${icon('plus')}</button></article>`).join('')}</div>`)}
function checkout(){if(!S.consent){toast('Give consent for registration and document checks first.',true);return}if(!S.registry||!['Active','Registered'].includes(S.registry.status)){toast('Verify an active GSTIN or Udyam registration first.',true);return}modal('One last look. Zero surprises.','Reserve this plan for review. This is a demo, with no payment or legal contract.',`<div class="quote-line"><span>Business</span><strong>${esc(S.registry.name)}</strong></div>${Q.items.map(p=>`<div class="quote-line"><span>${esc(p.name)} × ${p.quantity}</span><strong>${money(p.monthly)} + GST</strong></div>`).join('')}<div class="quote-line total"><span>Monthly bill, incl. GST</span><strong>${money(Q.total,2)}</strong></div><div class="quote-line"><span>Setup, incl. GST</span><strong>${money(Q.setup_total,2)}</strong></div><div class="quote-line"><span>First invoice estimate</span><strong>${money(Q.first_invoice,2)}</strong></div><p>Maximum minimum term: ${Q.contract} months. Individual service terms appear in your quote. Estimated installation: ${Q.days} days after verification and site feasibility. Your current check status is: <b>${esc(S.kyc.label)}</b>.</p><label class="checkbox-label"><input type="checkbox" id="accept-quote"><span>I reviewed the prices and understand that this demo reservation stays in review until all verification checks are resolved.</span></label>`,`<button class="button secondary" data-action="close">Keep editing</button><button class="button" data-action="reserve">Reserve my demo plan${icon('arrow')}</button>`)}
async function updateQuote(items){const q=await api('quote',{profile:S.profile,items});S.items={...items};Q=q;sessionStorage.removeItem('udyam_checkout');render();}
async function buildPlan(p=wizard){wizardEdit='';const result=await api('recommend',{profile:{...p,language}});S.profile=result.profile;S.items=result.items;S.plan=result;Q=result.quote;sessionStorage.removeItem('udyam_checkout');wizard={...result.profile};quoteMode='recommended';go('bundle');}
function downloadQuote(){if(!Q)return;const doc=`<!doctype html><html><meta charset="utf-8"><title>Udyam quote</title><style>body{font:14px system-ui;max-width:800px;margin:60px auto;padding:20px;color:#29233b}h1{color:#6855de}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #eee;padding:12px 5px}small{color:#777}p{line-height:1.8}</style><h1>udyam. / Accel Business</h1><h2>Your transparent quote</h2><p>Business: ${esc(S.registry?.name||businessName(S.profile))}<br>Prepared: ${esc(new Date().toLocaleDateString('en-IN'))}<br>Catalogue starting rates · synthetic local demo</p><table><tr><th>Service</th><th>Qty</th><th>Monthly, excl. GST</th><th>Setup, excl. GST</th><th>Min. term</th></tr>${Q.items.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.quantity}</td><td>${money(p.monthly,2)}</td><td>${money(p.setup,2)}</td><td>${p.contract} months</td></tr>`).join('')}</table><p>Monthly subtotal: ${money(Q.subtotal,2)}<br>Estimated GST (18%): ${money(Q.tax,2)}<br><b>Monthly total: ${money(Q.total,2)}</b><br>Setup including GST: ${money(Q.setup_total,2)}<br>First invoice estimate: ${money(Q.first_invoice,2)}<br>12-month cash outlay including setup: ${money(Q.annual,2)}</p><p>Install estimate: ${Q.days} days after KYC and feasibility approval. This is not a binding contract, a serviceability promise or a payment request. Quotes use minimum catalogue prices; final commercial approval is required. Individual minimum contract terms remain applicable beyond the 12-month illustration where shown.</p></html>`;const url=URL.createObjectURL(new Blob([doc],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Udyam-business-quote.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Quote downloaded, with every service, term and tax shown.');}
document.addEventListener('click', event=>{if(event.target.closest('.skip-link')){event.preventDefault();$('main').focus();return}const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,value=el.dataset.value;event.preventDefault();if(action==='close'){$('modal').close();return}if(action==='menu'){$('sidebar').classList.toggle('open');syncNav();return}if(action==='privacy'){privacy();return}if(action==='help'){help();return}if(action==='scenarios'){scenarios();return}if(action==='download'){downloadQuote();return}if(action==='catalogue'){showCatalogue();return}if(action==='checkout'){checkout();return}if(action==='goto'){go(value);return}if(action==='start'){wizardEdit='';wizard={language};messages=[];selectedGoals=[];go('advisor');return}if(action==='business'){wizard={segment:value,language};messages=[t('I run a '+businessName(wizard)+'.','मेरा व्यवसाय '+businessTypes.find(b=>b.id===value)?.hi+' है।')];selectedGoals=[];go('advisor');return}if(action==='choose-business'){wizardEdit='';wizard.segment=value;messages.push(t('I run a '+businessName(wizard)+'.','मेरा व्यवसाय '+businessTypes.find(b=>b.id===value)?.hi+' है।'));render();return}if(action==='goal'){selectedGoals=selectedGoals.includes(value)?selectedGoals.filter(n=>n!==value):[...selectedGoals,value];render();return}if(action==='edit-field'){wizardEdit=value;if(value==='needs')selectedGoals=[...(wizard.needs||[])];render();return}if(action==='confirm-goals'){if(!selectedGoals.length){toast(t('Choose at least one goal.','कम से कम एक लक्ष्य चुनें।'),true);return}wizardEdit='';wizard.needs=[...selectedGoals];messages.push(t('My priorities: ','मेरी प्राथमिकताएँ: ')+selectedGoals.map(k=>{let g=goals.find(g=>g.id===k);return t(g.name,g.hi)}).join(', '));render();return}if(action==='restart-advisor'){wizardEdit='';wizard={language};messages=[];selectedGoals=[];render();return}if(action==='registry-kind'){registryKind=value;render();return}if(action==='partner-tab'){partnerTab=value;render();return}if(action==='open-operations'){partnerTab='orders';analyticsData=null;go('partner');return}if(action==='listen'){if(!('speechSynthesis' in window)){toast('Speech playback is unavailable in this browser.',true);return}speechSynthesis.cancel();const content=$('advisor-question')?.textContent||S.plan?.explanation||'';const speech=new SpeechSynthesisUtterance(content);speech.lang=language==='Hindi'?'hi-IN':'en-IN';speech.rate=.9;speechSynthesis.speak(speech);return}if(action==='confirm-withdraw'){modal('Delete this workspace?','This removes your saved plan, extracted details, orders and help requests from the local database.',`<p>The original supplied synthetic dataset is unchanged. This action clears the current browser workspace; it does not manage operating-system backups.</p>`,`<button class="button secondary" data-action="close">Keep my workspace</button><button class="button danger" data-action="withdraw">Delete my workspace</button>`);return}
task(async()=>{
 if(action==='language'){language=language==='English'?'Hindi':'English';wizard.language=language;if(S.profile.segment){S.profile.language=language;setState(await api('profile',{profile:S.profile}))}render();return}
 if(action==='build-plan'){await buildPlan();return}
 if(action==='scenario'){
  const common={sites:1,tier:'1',fibre:'available',has_gstin:false,language};
  const samples={micro:{segment:'micro',employees:3,seats:2,city:'Jaipur',tier:'2',budget:2500,current_spend:2500,needs:['internet','billing','customers']},prof:{segment:'prof',employees:8,seats:8,city:'Pune',budget:6000,current_spend:6500,needs:['internet','email','security','backup']},multi:{segment:'multi',employees:24,sites:3,seats:10,city:'Mumbai',budget:18000,current_spend:19000,needs:['internet','backup','billing','cctv','email']},mfg:{segment:'mfg',employees:18,seats:10,city:'Indore',tier:'2',budget:25000,current_spend:28000,has_gstin:true,needs:['internet','security','machines','email']}};
  wizard={...common,...samples[value]};$('modal').close();await buildPlan(wizard);toast('Example loaded. Edit any goal or quantity to make it yours.');return
 }
 if(action==='quantity'){const items={...S.items};const quantity=items[value]+Number(el.dataset.delta);if(quantity<1)return;if(quantity>1000)throw Error('The maximum quantity is 1,000.');items[value]=quantity;quoteMode='custom';await updateQuote(items);return}
 if(action==='remove'){const items={...S.items};delete items[value];quoteMode='custom';await updateQuote(items);return}
 if(action==='lean'){const keys=Object.keys(S.items);const key=keys.find(k=>['P01','P02','P03','P04','P05','P06'].includes(k))||keys[0];await updateQuote({[key]:S.items[key]});quoteMode='lean';render();return}
 if(action==='recommended'){await buildPlan(S.profile);return}
 if(action==='add-product'){const items={...S.items,[value]:(S.items[value]||0)+1};await updateQuote(items);quoteMode='custom';showCatalogue();toast('Service added. Your quote is updated.');return}
 if(action==='demo-registry'){setState(await api('lookup',{kind:'gst',value:'19EOGXH4115Y1ZL'}));registryKind='gst';render();toast('K02’s synthetic business registration is verified.');return}
 if(action==='specimen'){toast('Reading the specimen on this computer…');setState(await api('specimen',{applicant:currentApplicant,kind:value}));render();toast('Document read. Check results are ready.');return}
 if(action==='reserve'){if(!$('accept-quote')?.checked)throw Error('Review and confirm the demo quote before reserving.');const idempotency=sessionStorage.getItem('udyam_checkout')||crypto.randomUUID();sessionStorage.setItem('udyam_checkout',idempotency);const order=await api('order',{accept:true,idempotency});S.orders=[order,...S.orders.filter(o=>o.id!==order.id)];selectedOrder=order.id;analyticsData=null;$('modal').close();go('orders');toast('Plan reserved. Your next steps are now in the tracker.');return}
 if(action==='refresh-order'){const o=S.orders.find(o=>o.id===selectedOrder)||S.orders[0];const updated=await api('order/'+encodeURIComponent(o.id));S.orders=S.orders.map(o=>o.id===updated.id?updated:o);render();toast('Showing the latest recorded status.');return}
 if(action==='followup'){const lead=analyticsData.queue.find(l=>l.id===value);const ticket=await api('callback',{topic:lead.id+' · '+lead.action+' · '+lead.business});analyticsData=null;await loadAnalytics();toast(ticket.id+' added to the local partner queue. No call sent.');return}
 if(action==='withdraw'){await api('withdraw',{});sessionStorage.removeItem('udyam_checkout');$('modal').close();S={profile:{},items:{},documents:{},orders:[],consent:false,kyc:{checks:[],state:'incomplete'}};Q=null;wizard={};messages=[];analyticsData=null;const boot=await api('bootstrap');setState(boot.state);go('overview');toast('Workspace deleted. You’re back in control.');return}
 });
});
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();const data=Object.fromEntries(new FormData(form));task(async()=>{
 if(form.id==='team-form'){wizardEdit='';wizard={...wizard,employees:Number(data.employees),sites:Number(data.sites),seats:Number(data.seats),city:data.city.split('|')[0],tier:data.city.split('|')[1]};messages.push(`${wizard.employees} ${t('people','लोग')}, ${wizard.sites} ${t('location(s) in','जगह,')} ${wizard.city}.`);render();return}
 if(form.id==='budget-form'){wizardEdit='';wizard={...wizard,budget:Number(data.budget),current_spend:Number(data.current_spend),fibre:data.fibre,has_gstin:data.has_gstin==='true'};messages.push(t('My monthly budget is ','मेरा मासिक बजट है ')+money(wizard.budget)+t(', including GST.',' GST सहित।'));await buildPlan();return}
 if(form.id==='chat-form'){const message=data.message.trim();if(!message)return;const response=await api('advisor',{profile:wizard,message});wizardEdit='';wizard={...response.profile,language};messages.push(message);render();return}
 if(form.id==='registry-form'){setState(await api('lookup',{kind:registryKind,value:data.identifier}));render();toast('Registry checked. Review the result below.');return}
 if(form.id==='help-form'){const result=await api('callback',{topic:data.topic});analyticsData=null;modal('You won’t need to start over.',result.id+' · Saved in your local partner queue.',`<div class="registry-result">${icon('circlecheck')}<div><strong>Your help request is saved.</strong><p>${esc(data.topic)}</p></div></div><p>Your plan and verification progress remain in this workspace. This demo has not placed an external call or sent a message.</p>`,`<button class="button secondary" data-action="close">Back to my setup</button><button class="button" data-action="view-handoff">See partner handoff${icon('arrow')}</button>`);return}
 if(form.matches('.operator-form')){const result=await api('order/advance',{id:form.dataset.order,note:data.note,...(data.date?{date:data.date}:{})});S.orders=S.orders.map(o=>o.id===result.id?result:o);analyticsData=null;await loadAnalytics();toast(result.events.at(-1).title+'. The customer tracker is updated.');return}
 });
});
document.addEventListener('click',event=>{if(event.target.closest('[data-action="view-handoff"]')){$('modal').close();partnerTab='orders';go('partner')}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='applicant'){currentApplicant=el.value;render();return}if(el.id==='catalogue-category'){catalogueFilter=el.value;showCatalogue();return}if(el.id==='order-select'){selectedOrder=el.value;render();return}if(el.dataset.change==='consent'){task(async()=>{setState(await api('consent',{consent:el.checked}));render();toast(S.consent?'Consent saved. You can now verify your business.':'Consent paused. No further verification will run. Use privacy controls to delete stored data.');});return}if(el.dataset.upload){const file=el.files[0];if(!file)return;if(file.size>8000000){toast('Choose an image smaller than 8 MB.',true);return}if(!S.consent){toast('Consent is needed before a document can be read.',true);el.value='';return}task(async()=>{toast('Reading the image locally. This can take a few seconds…');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('Could not open this image.'));r.readAsDataURL(file)});setState(await api('document',{kind:el.dataset.upload,data}));render();toast('Document read. Your checks are updated.');});}});
document.addEventListener('input',event=>{if(event.target.id==='budget-slider'){$('budget-display').textContent=money(event.target.value);$('budget-number').value=event.target.value}if(event.target.id==='budget-number'){$('budget-display').textContent=money(event.target.value);$('budget-slider').value=Math.max(1000,Math.min(50000,Number(event.target.value)))}});
document.addEventListener('keydown',event=>{if(event.target.matches('#chat-form textarea')&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();event.target.form.requestSubmit()}});
$('modal').addEventListener('click',event=>{if(event.target===$('modal')){const bounds=$('modal').getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)$('modal').close()}});
window.addEventListener('resize',syncNav);
window.addEventListener('hashchange',()=>{$('sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})});
async function init(){try{const boot=await api('bootstrap');setState(boot.state);CAT=boot.catalogue;capabilities=boot.capabilities;wizard={...S.profile,language};if(Object.keys(S.items).length){Q=await api('quote',{profile:S.profile,items:S.items});if(JSON.stringify(S.items)!==JSON.stringify(S.plan?.items||{}))quoteMode='custom'}render()}catch(error){$('main').innerHTML=`<section class="panel empty-state"><h2>We couldn’t open your workspace.</h2><p>${esc(error.message)}</p><button class="button" data-action="reload">Try again</button></section>`;document.querySelector('[data-action="reload"]')?.addEventListener('click',()=>location.reload());}}
init();
